import 'package:flutter/material.dart';
import 'package:cloud_firestore/cloud_firestore.dart';
import '../models/usuario.dart';
import '../services/auth_service.dart';
import '../services/usuario_service.dart';
import '../widgets/async_ui.dart';
import 'animal_page.dart';
import 'animal_form.dart';
import 'pedidos_page.dart';
import 'admin_page.dart';
class HomePage extends StatefulWidget {final Usuario usuario;const HomePage({super.key,required this.usuario});@override State<HomePage> createState()=>_HomePageState();}
class _HomePageState extends State<HomePage>{int indice=0;
 Widget menu(String titulo,IconData icon,Widget pagina)=>Card(child:ListTile(leading:Icon(icon),title:Text(titulo),trailing:const Icon(Icons.chevron_right),onTap:()=>abrir(context,pagina)));
 @override Widget build(BuildContext context){final admin=widget.usuario.tipo=='admin';final inicio=Scaffold(appBar:AppBar(title:Text(admin?'AdotaPet Admin':'AdotaPet'),actions:[IconButton(onPressed:()=>AuthService().logout(),icon:const Icon(Icons.logout))]),body:ListView(padding:const EdgeInsets.all(16),children:[const Icon(Icons.pets,size:65,color:Color(0xff276749)),const Text('Um novo lar. Uma nova história.',textAlign:TextAlign.center),if(admin)...[menu('Dashboard',Icons.dashboard,const DashboardPage()),menu('Gerenciar usuários',Icons.people,const AdminUsuariosPage()),menu('Gerenciar e aprovar animais',Icons.pets,const AnimalPage(modo:'admin')),menu('Gerenciar adoções',Icons.assignment,const PedidosPage(modo:'admin'))]else ...[menu('Quero adotar',Icons.favorite,const AnimalPage(modo:'catalogo')),menu('Cadastrar animal',Icons.add_circle,const AnimalForm()),menu('Meus animais',Icons.pets,const AnimalPage(modo:'meus')),menu('Minhas solicitações',Icons.assignment,const PedidosPage(modo:'enviadas')),menu('Solicitações recebidas',Icons.inbox,const PedidosPage(modo:'recebidas'))],menu('Meu perfil',Icons.person,PerfilPage(uid:widget.usuario.uid))]));if(admin)return inicio;return Scaffold(body:[inicio,const AnimalPage(modo:'catalogo'),const AnimalPage(modo:'meus'),const PedidosPage(modo:'enviadas')][indice],bottomNavigationBar:BottomNavigationBar(type:BottomNavigationBarType.fixed,currentIndex:indice,onTap:(v)=>setState(()=>indice=v),items:const [BottomNavigationBarItem(icon:Icon(Icons.home),label:'Início'),BottomNavigationBarItem(icon:Icon(Icons.favorite),label:'Adotar'),BottomNavigationBarItem(icon:Icon(Icons.pets),label:'Animais'),BottomNavigationBarItem(icon:Icon(Icons.assignment),label:'Pedidos')]));}
}
class PerfilPage extends StatelessWidget{final String uid;const PerfilPage({super.key,required this.uid});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Meu perfil')),body:FutureBuilder<DocumentSnapshot<Map<String,dynamic>>>(future:FirebaseFirestore.instance.collection('usuarios').doc(uid).get(),builder:(context,s){if(s.hasError)return erro(s.error);if(!s.hasData)return espera();return PerfilForm(usuario:Usuario(uid,s.data!.data()!));}));}
class PerfilForm extends StatefulWidget{final Usuario usuario;const PerfilForm({super.key,required this.usuario});@override State<PerfilForm> createState()=>_PerfilFormState();}
class _PerfilFormState extends State<PerfilForm>{late final TextEditingController nome,telefone,cidade;bool ocupado=false;@override void initState(){super.initState();nome=TextEditingController(text:widget.usuario.nome);telefone=TextEditingController(text:widget.usuario.telefone);cidade=TextEditingController(text:widget.usuario.cidade);}@override void dispose(){nome.dispose();telefone.dispose();cidade.dispose();super.dispose();}@override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(16),children:[Text(widget.usuario.email),TextField(controller:nome,maxLength:150,decoration:const InputDecoration(labelText:'Nome')),TextField(controller:telefone,maxLength:30,decoration:const InputDecoration(labelText:'Telefone')),TextField(controller:cidade,maxLength:150,decoration:const InputDecoration(labelText:'Cidade')),FilledButton(onPressed:ocupado?null:()async{setState(()=>ocupado=true);await executar(context,()=>UsuarioService().perfil(nome.text,telefone.text,cidade.text));if(mounted)setState(()=>ocupado=false);},child:const Text('Salvar')),TextButton(onPressed:()=>executar(context,()=>AuthService().recuperar(widget.usuario.email)),child:const Text('Solicitar alteração de senha'))]);}
